fun uploadImagesToFirebase(storage: FirebaseStorage, uris: List<Uri>, onComplete: (List<String>) -> Unit){
    if (uris.isEmpty()) { onComplete(emptyList()); return }
    val uploadedUrls = mutableListOf<String>()
    var count = 0
