/**
 * Creates a temporary image URI for camera capture using FileProvider
 */
fun createImageUri(context: android.content.Context): Uri {
    val timeStamp = SimpleDateFormat("yyyyMMdd_HHmmss", Locale.getDefault()).format(Date())
    val imageFileName = "SPOT_${timeStamp}.jpg"

    // Create the camera_images directory if it doesn't exist
    val cacheDir = File(context.cacheDir, "camera_images")
    if (!cacheDir.exists()) {
        cacheDir.mkdirs()
    }

    val imageFile = File(cacheDir, imageFileName)

    return FileProvider.getUriForFile(
        context,
        "${context.packageName}.fileprovider",
        imageFile
    )
}

/**
 * Search for an address and return LatLng coordinates
 * Works on all Android versions with proper main thread callback
 */
fun searchAddress(context: android.content.Context, query: String, onResult: (LatLng?) -> Unit) {
    val handler = Handler(Looper.getMainLooper())
    try {
        val geocoder = Geocoder(context, Locale.getDefault())
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.TIRAMISU) {
            geocoder.getFromLocationName(query, 1) { addresses ->
                handler.post {
                    if (addresses.isNotEmpty()) {
                        val address = addresses[0]
                        onResult(LatLng(address.latitude, address.longitude))
                    } else {
                        onResult(null)
                    }
                }
            }
        } else {
            // Run synchronously on background thread for older versions
            Thread {
                try {
                    @Suppress("DEPRECATION")
                    val addresses = geocoder.getFromLocationName(query, 1)
                    handler.post {
                        if (!addresses.isNullOrEmpty()) {
                            val address = addresses[0]
                            onResult(LatLng(address.latitude, address.longitude))
                        } else {
                            onResult(null)
                        }
                    }
                } catch (e: Exception) {
                    handler.post { onResult(null) }
                }
            }.start()
        }
    } catch (e: Exception) {
        handler.post { onResult(null) }
    }
}

